import numpy as np

def kernel(x, g, eps):
    M, N = x.shape
    y = np.zeros_like(x, dtype=np.float32)

    # First pass: compute row-wise sum of squares
    row_sum_sq = np.zeros(M, dtype=np.float32)
    for j in range(N):
        for i in range(M):
            row_sum_sq[i] += x[i, j] ** 2

    # Compute RMS for each row
    norm = np.sqrt(row_sum_sq / N + eps)

    # Second pass: apply normalization and scaling
    for i in range(M):
        for j in range(N):
            y[i, j] = x[i, j] / norm[i] * g[j]

    return y

