def kernel(x):
    M, N = x.shape
    result = np.empty((N, M), dtype=np.float32)
    tile_size = (128, 512)

    for i in range(0, M, tile_size[0]):
        for j in range(0, N, tile_size[1]):
            end_i = min(i + tile_size[0], M)
            end_j = min(j + tile_size[1], N)
            # Extract tile from x
            tile_x = x[i:end_i, j:end_j]
            # Transpose the tile using explicit loops
            for r in range(i, end_i):
                for c in range(j, end_j):
                    result[c, r] = tile_x[r - i, c - j]
    return result

